voiced.voice/rules.json:
{
  "version": 1,
  "channels": [
    "email",
    "linkedin-note",
    "linkedin-dm"
  ],
  "allow": [
    "If it looks like a fit, I'd love the opportunity to have a conversation about it."
  ],
  "limits": {
    "linkedin-note": {
      "max_chars": 300,
      "level": "fail"
    }
  },
  "rules": [
    {
      "id": "no-timeboxed-call",
      "level": "fail",
      "type": "regex",
      "pattern": "\\b(\\d+|fifteen)[- ]?minutes?\\b",
      "flags": "i",
      "message": "No time-boxed call asks."
    }
  ]
}

